for _ in range(MINES):
    row, col = random.randint(0, ROWS-1), random.randint(0, COLS-1)
    while board[row][col] == -1:
        row, col = random.randint(0, ROWS-1), random.randint(0, COLS-1)
    board[row][col] = -1

# 计算每个方格周围的地雷数量
for row in range(ROWS):
    for col in range(COLS):
        if board[row][col] != -1:
            count = 0
            for r in range(max(0, row-1), min(row+2, ROWS)):
                for c in range(max(0, col-1), min(col+2, COLS)):
                    if board[r][c] == -1:
                        count += 1
            board[row][col] = count

# 显示游戏板（方便测试）
for row in board:
    print(row)

这个示例代码首先创建一个ROWS x COLS的游戏板，然后随机放置MINES个地雷。接下来，它计算每个方格周围的地雷数量，并在游戏板上显示结果。

请注意，此示例代码不包括游戏界面或交互性，但可以作为构建更复杂游戏的基础。例如，您可以使用Tkinter或其他GUI库创建游戏界面，并添加逻辑以处理玩家的单击操作。

